SELECT d.DELINQUENCY_ID, d.LOAN_ID, l.LOAN_ACCOUNT_NO, a.APPLICATION_NO, p.FULL_NAME_AR APPLICANT_NAME_AR, f.ORG_NAME_AR FINANCIER_NAME_AR, d.START_DATE, d.STAGE_CODE, s.NAME_AR STAGE_NAME_AR, d.DAYS_PAST_DUE, d.OVERDUE_AMOUNT, d.OVERDUE_INSTALLMENTS, d.STATUS, d.COLLECTION_ACTION_AR, l.OUTSTANDING_PRINCIPAL FROM MFF_DELINQUENCIES d JOIN MFF_LOANS l ON l.LOAN_ID = d.LOAN_ID JOIN MFF_APPLICATIONS a ON a.APPLICATION_ID = l.APPLICATION_ID JOIN MFF_PERSONS p ON p.PERSON_ID = a.PRIMARY_PERSON_ID JOIN MFF_ORGANIZATIONS f ON f.ORG_ID = a.FINANCIER_ID JOIN REF_MFF_DELINQUENCY_STAGE s ON s.CODE = d.STAGE_CODE WHERE NVL(d.STATUS,'OPEN') <> 'CLOSED';
